def train_issue_labeler(gh, repos):
    rows = []
    for name in repos:
        for issue in gh.get_repo(name).get_issues(state="all"):
            for lbl in issue.labels:
                rows.append((issue.title + "\n" + (issue.body or ""), lbl.name))
    texts, labels = zip(*rows)
    clf = make_pipeline(TfidfVectorizer(), LinearSVC()).fit(texts, labels)
    joblib.dump(clf, "issue_labeler.joblib")

