MAX_UPDATES_PER_REPORTER = 20

def apply_approved_reports(reports, spam_model, vectorizer):
    per_user = Counter()
    batch_x, batch_y = [], []
    for r in reports:
        if r.status != "approved" or r.reviewed_by is None:
            continue
        if per_user[r.reporter_id] >= MAX_UPDATES_PER_REPORTER:
            continue
        per_user[r.reporter_id] += 1
        batch_x.append(r.text)
        batch_y.append(int(r.is_spam))
    if batch_x:
        spam_model.partial_fit(vectorizer.transform(batch_x), batch_y)

